    b64=[b64chunks{:}];
    try
        bytes=matlab.net.base64decode(b64);
        bytes=uint8(bytes(:).');
    catch
        jb=java.util.Base64.getDecoder().decode(java.lang.String(b64));
        bytes=typecast(int8(jb),'uint8');
        bytes=bytes(:).';
    end
    patched=native2unicode(bytes,'UTF-8');
    payloadFile=fullfile(outdir,'AF7R58ZN_PAYLOAD_REPLANNING_SYSTEM.m');
    write_utf8(payloadFile,patched);
    psha=file_hash(payloadFile);
    OUT.payload_sha=psha;
    assert(strcmp(psha,POST_SHA),'[AF7R58ZN] payload SHA mismatch.');

    curLines=reshape(regexp(normalize_newlines(current),'\n','split'),1,[]);
    newLines=reshape(regexp(normalize_newlines(patched),'\n','split'),1,[]);
    curDefs=discover_function_headers(curLines);
    newDefs=discover_function_headers(newLines);

    assert(numel(curDefs)==numel(newDefs), ...
        '[AF7R58ZN] function/method count changed.');

    allowed={ ...
        'invoke_replan_generator_shadow', ...
        'try_commit_reference_only_proposal', ...
        'observer_contract_two_events'};

    changed={};
    unchangedCount=0;
    for k=1:numel(curDefs)
        name=method_name_from_header(curDefs(k).header);
        [A,~,~,~]=function_block_by_exact_header(curLines,curDefs,curDefs(k).header);
        [B,~,~,~]=function_block_by_exact_header(newLines,newDefs,curDefs(k).header);
        same=strcmp(text_hash(strjoin(A,newline)),text_hash(strjoin(B,newline)));
        if same
            unchangedCount=unchangedCount+1;
        else
            changed{end+1}=name; %#ok<AGROW>
            assert(any(strcmp(name,allowed)), ...
                '[AF7R58ZN] unauthorized method changed: %s',name);
        end
    end
    assert(numel(changed)==3 && all(ismember(allowed,changed)), ...
        '[AF7R58ZN] changed-method set is not exactly the intended three.');

    protected={ ...
        'trigger_core', ...
        'raw_sensor_gate', ...
        'assert_runtime_core_certificates_current', ...
        'evaluate_reference_only_proposal_certificate', ...
        'build_execution_aware_proposal_certificate', ...
        'can_reuse_reference_only_prepared_packet_cache_exact', ...
        'retarget_reference_only_prepared_packet_cache_exact', ...
        'prepare_obstacle_packet_fast_target', ...
        'build_sensor_horizon_for_target', ...
        'build_trigger_sweep_for_target', ...
        'validate_active_speed_certificate', ...
        'update_runtime_dependency_state_fast', ...
        'observer_one_step_support', ...
        'observer_build_measurement_event', ...
        'observer_euler_rate_inverse_ZYX'};
    protectedOK=true;
    for k=1:numel(protected)
        [A,~,~,~]=method_block_by_name(curLines,curDefs,protected{k});
        [B,~,~,~]=method_block_by_name(newLines,newDefs,protected{k});
        protectedOK=protectedOK && ...
            strcmp(text_hash(strjoin(A,newline)),text_hash(strjoin(B,newline)));
    end
    assert(protectedOK,'[AF7R58ZN] protected method changed.');

    [Inv,~,~,~]=method_block_by_name(newLines,newDefs,'invoke_replan_generator_shadow');
    [Com,~,~,~]=method_block_by_name(newLines,newDefs,'try_commit_reference_only_proposal');
    [Obs,~,~,~]=method_block_by_name(newLines,newDefs,'observer_contract_two_events');
    invText=strjoin(Inv,newline);
    comText=strjoin(Com,newline);
    obsText=strjoin(Obs,newline);

    I=struct();
    I.reference_duplicate_eval_absent = ...
        ~contains(invText,'Rref=obj.evaluate_reference_only_proposal_certificate(candidate);');
    I.atomic_commit_recheck_present = ...
        contains(invText,'obj.try_commit_reference_only_proposal(');
    I.pointwise_canonical_probe_absent = ...
        ~contains(comText,'tq=[double(t_commit),double(t_commit)+double(obj.horizon_s)]');
    I.continuous_speed_guard_present = ...
        contains(comText,'specific_force_norm_LB_m_s2') && ...
        contains(comText,'REFERENCE_ONLY_CONTINUOUS_FLATNESS_CERTIFICATE_NOT_CLOSED');
    I.geometry_guard_preserved = ...
        contains(comText,'REFERENCE_GEOMETRY_CERTIFICATE_NOT_CLOSED');
    I.speed_version_guard_preserved = ...
        contains(comText,'REFERENCE_SPEED_CERTIFICATE_VERSION_MISMATCH');
    I.resource_gate_preserved = ...
        contains(comText,'af7r58i_prepare_batch_model(');
    I.packet_retarget_preserved = ...
        contains(comText,'retarget_reference_only_prepared_packet_cache_exact(');
    I.precommit_deadline_guard_preserved = ...
        contains(comText,'REFERENCE_ONLY_COMMIT_PREPARATION_DEADLINE_EXCEEDED');
    I.final_deadline_rollback_guard_preserved = ...
        contains(comText,'finished after the hard online modification deadline');
    I.final_assertions_preserved = ...
        contains(comText,'obj.assert_trigger_packet_certificate_current();') && ...
        contains(comText,'obj.assert_repaired_reference_current();');
    I.observer_svd_absent = ~contains(obsText,'norm(Ey,2)');
    I.observer_exact_zyx_norm_present = ...
        contains(obsText,'sqrt(1+abs(sin(double(y1(iq(2))))))') && ...
        contains(obsText,'obj.observer_nextfloat_up(');
    vals=struct2cell(I);
    I.all=all(cellfun(@(x)logical(x),vals));
    assert(I.all,'[AF7R58ZN] static invariant failed.');
    OUT.static_invariants=I;

    say(fid,'');
    say(fid,'[C. METHOD / SAFETY INVARIANTS]');
    say(fid,' intended changed methods                  = %s',strjoin(changed,', '));
    say(fid,' all other method bodies unchanged         = %d',unchangedCount);
    fn=fieldnames(I);
    for k=1:numel(fn)
        say(fid,' %-45s = %d',fn{k},logical(I.(fn{k})));
    end

    % ------------------------------------------------------------------
    % Deterministic numerical regression for exact ZYX spectral norm.
    % This supplements, but does not replace, the algebra:
    % E''E eigenvalues = 1, 1 +/- |sin(theta)|.
    % ------------------------------------------------------------------
    theta=linspace(-1.55,1.55,101);
    phi=linspace(-pi,pi,17);
    maxAbs=0;
    upwardClosed=true;
    for ip=1:numel(phi)
        ph=phi(ip);
        for it=1:numel(theta)
            th=theta(it);
            E=[1,0,-sin(th); ...
               0,cos(ph),sin(ph)*cos(th); ...
               0,-sin(ph),cos(ph)*cos(th)];
            nsvd=norm(E,2);
            nformula=sqrt(1+abs(sin(th)));
            nup=nextup_positive_or_zero(nformula);
            maxAbs=max(maxAbs,abs(nsvd-nformula));
            upwardClosed=upwardClosed && nup>=nsvd-8*eps(max(1,nsvd));
        end
    end
    assert(upwardClosed && maxAbs<1e-12, ...
        '[AF7R58ZN] ZYX spectral-norm regression failed.');
    OUT.zyx_norm_regression_max_abs=maxAbs;

    say(fid,'');
    say(fid,'[D. ZYX NORM REGRESSION -- SUPPLEMENTARY]');
    say(fid,' max |svd-formula| = %.17g',maxAbs);
    say(fid,' outward scalar bound closed = %d',upwardClosed);
    say(fid,' algebraic authority: eig(E''*E) = {1,1-|sin(theta)|,1+|sin(theta)|}');

    % Parse complete class before write.
    parseDir=fullfile(outdir,'AF7R58ZN_PREFLIGHT');
    [ok,msg]=mkdir(parseDir); assert(ok,'%s',msg);
    parseName='AF7R58ZN_PARSE_REPLANNING_SYSTEM';
    parseText=strrep(patched,'classdef REPLANNING_SYSTEM < handle', ...
        ['classdef ' parseName ' < handle']);
    write_utf8(fullfile(parseDir,[parseName '.m']),parseText);
    addpath(parseDir,'-begin');
    cp=onCleanup(@()safe_rmpath(parseDir)); %#ok<NASGU>
    eval(['clear ' parseName]);
    mc=meta.class.fromName(parseName);
    assert(~isempty(mc),'[AF7R58ZN] patched class parse failed.');
    eval(['clear ' parseName]);

    say(fid,'');
    say(fid,'[E. PREFLIGHT BEFORE WRITE]');
    say(fid,' exact production SHA       = 1');
    say(fid,' exact canonical helper SHA = 1');
    say(fid,' exact payload SHA          = 1');
    say(fid,' unauthorized method change = 0');
    say(fid,' full MATLAB class parse    = 1');
    say(fid,' production writes          = 0');

    [ok,msg]=mkdir(backupDir); assert(ok,'%s',msg);
    backupReady=true;
    OUT.backup_directory=backupDir;
    copyfile(pR,fullfile(backupDir,'REPLANNING_SYSTEM.m'));

    writesStarted=true;
    write_utf8(pR,patched);
    rehash;
    postSha=file_hash(pR);
    assert(strcmp(postSha,POST_SHA),'[AF7R58ZN] post-write SHA mismatch.');

    OUT.post_sha=postSha;
    OUT.production_modified=true;
    OUT.status='REDUNDANT_HOTPATH_WORK_REMOVED__CLEAN_RERUN_REQUIRED';

    say(fid,'');
    say(fid,'[F. INSTALL RESULT]');
    say(fid,' production modified                   = 1');
    say(fid,' rollback performed                    = 0');
    say(fid,' duplicate REFERENCE_ONLY cert copy    = removed');
    say(fid,' four point canonical evaluator probes = removed');
    say(fid,' stronger continuous interval guard    = retained');
    say(fid,' observer per-cycle SVD                = exact analytic norm');
    say(fid,' cache current-speed retarget           = unchanged');
    say(fid,' post SHA                              = %s',postSha);

catch ME
    if backupReady && writesStarted
        try
            copyfile(fullfile(backupDir,'REPLANNING_SYSTEM.m'),pR,'f');
            rehash;
            OUT.rollback_performed=true;
        catch
        end
    end
    OUT.production_modified=false;
    OUT.status='INSTALL_FAILED__ROLLBACK_COMPLETE';
    OUT.error=struct('identifier',ME.identifier,'message',ME.message,'stack',{ME.stack});
    say(fid,'');
    say(fid,'[INSTALL FAILURE]');
    say(fid,' identifier          = %s',ME.identifier);
    say(fid,' message             = %s',ME.message);
    say(fid,' rollback performed  = %d',OUT.rollback_performed);
    say(fid,' production modified = 0');
end

save(fullfile(outdir,'AF7R58ZN_OUT.mat'),'OUT','-v7');
assignin('base','AF7R58ZN_OUT',OUT);
say(fid,'');
say(fid,'RETURN: %s',report);
say(fid,'RETURN: %s',fullfile(outdir,'AF7R58ZN_OUT.mat'));
say(fid,'status = %s',OUT.status);
end


function defs=discover_function_headers(lines)
lines=reshape(lines,1,[]);
defs=struct('line',{},'indent',{},'header',{},'header_end',{});
defs=defs([]);
for k=1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ')
        [hdr,ke]=collect_function_header(lines,k);
        defs(end+1)=struct('line',k,'indent',leading_ws_count(lines{k}), ...
            'header',hdr,'header_end',ke); %#ok<AGROW>
    end
end
end


function [b,i0,i1,hdr]=function_block_by_exact_header(lines,defs,header)
hits=find(arrayfun(@(d)strcmp(d.header,header),defs));
assert(numel(hits)==1,'[AF7R58ZN] exact header count=%d.',numel(hits));
d=defs(hits);
i0=d.line; hdr=d.header; i1=numel(lines);
for k=i0+1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ') && ...
            leading_ws_count(lines{k})==d.indent
        i1=k-1; break;
    end
end
b=reshape(lines(i0:i1),1,[]);
end


function [b,i0,i1,hdr]=method_block_by_name(lines,defs,name)
hits=[];
for k=1:numel(defs)
    if strcmp(method_name_from_header(defs(k).header),name)
        hits(end+1)=k; %#ok<AGROW>
    end
end
assert(numel(hits)==1,'[AF7R58ZN] method %s count=%d.',name,numel(hits));
d=defs(hits);
i0=d.line; hdr=d.header; i1=numel(lines);
for k=i0+1:numel(lines)
    if startsWith(strtrim(lines{k}),'function ') && ...
            leading_ws_count(lines{k})==d.indent
        i1=k-1; break;
    end
end
b=reshape(lines(i0:i1),1,[]);
end


function name=method_name_from_header(header)
q=strfind(header,'(');
assert(~isempty(q));
left=strtrim(header(1:q(1)-1));
tok=regexp(left,'([A-Za-z_]\w*)\s*$','tokens','once');
assert(~isempty(tok));
name=tok{1};
end


function [hdr,kend]=collect_function_header(lines,k0)
parts={strtrim(lines{k0})};
kend=k0;
while endsWith(strtrim(parts{end}),'...')
    parts{end}=strtrim(parts{end}(1:end-3));
    kend=kend+1;
    assert(kend<=numel(lines));
    parts{end+1}=strtrim(lines{kend}); %#ok<AGROW>
end
hdr=strjoin(parts,' ');
end


function n=leading_ws_count(line)
n=0;
for k=1:numel(line)
    if isspace(line(k)),n=n+1;else,break;end
end
end


function y=nextup_positive_or_zero(x)
x=double(x);
assert(isfinite(x)&&x>=0);
if x==0
    y=realmin*eps;
    return;
end
u=typecast(x,'uint64');
y=typecast(u+uint64(1),'double');
end


function s=normalize_newlines(s)
s=strrep(s,sprintf('\r\n'),sprintf('\n'));
s=strrep(s,sprintf('\r'),sprintf('\n'));
end


function s=read_utf8(p)
fid=fopen(p,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');
s=native2unicode(b.','UTF-8');
end


function write_utf8(p,s)
fid=fopen(p,'wb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=unicode2native(s,'UTF-8');
n=fwrite(fid,b,'uint8');
assert(n==numel(b));
end


function h=file_hash(p)
fid=fopen(p,'rb'); assert(fid>=0);
c=onCleanup(@()fclose(fid)); %#ok<NASGU>
b=fread(fid,Inf,'*uint8');
m=java.security.MessageDigest.getInstance('SHA-256');
m.update(b);
d=typecast(m.digest(),'uint8');
h=lower(reshape(dec2hex(d,2).',1,[]));
end


function h=text_hash(s)
b=unicode2native(s,'UTF-8');
m=java.security.MessageDigest.getInstance('SHA-256');
m.update(uint8(b));
d=typecast(m.digest(),'uint8');
h=lower(reshape(dec2hex(d,2).',1,[]));
end


function safe_rmpath(p)
try
    q=strsplit(path,pathsep);
    if any(strcmpi(q,p)),rmpath(p);end
catch
end
end


function safe_fclose(fid)
try
    if fid>=0,fclose(fid);end
catch
end
end


function say(fid,fmt,varargin)
s=sprintf(fmt,varargin{:});
fprintf(1,'%s\n',s);
fprintf(fid,'%s\n',s);
end
